module Box(Origin: number, Fail: boolean) {
export point Prefix = coordinate(x: Origin, y: 1)
const Bad: line = segment(start: (1 / 0,9), end: (1 / 0 + 3,9 + 4))
const Good0: line = segment(start: (Origin + 2,9), end: (Origin + 2 + 3,9 + 4))
const Good1: line = segment(start: (Origin + 17,33), end: (Origin + 17 + 3,33 + 4))
const Other: line = segment(start: (Origin + 40,33), end: (Origin + 40 + 3,33 + 4))
const Chosen: line[] = if (Fail) { [Bad,Other] } else { [Good0,Good1] }
const Ticks: number[] = [1]
for Tick in Ticks carry Carried: line[] = Chosen {
const First: line = Carried[0]
const Second: line = Carried[1]
const Swap: line[] = [Second,First]
next Carried = Swap
}
const Final0: line = Carried[0]
const Final1: line = Carried[1]
export line Mark = segment(start: Final0.end, end: Final1.start)
}
instance Dormant(enabled: false) = Box(Origin: 1 / 0, Fail: true)
instance One = Box(Origin: 10, Fail: true)
line UseOne = from(source: One::Mark)
instance Two = Box(Origin: 60, Fail: false)
