module Sleeve(span: number = 60, lift: number = 40) {
  export curve Cap = bezier(start: (0, 0), end: (span, lift), startAngle: 90, startLength: 20, endAngle: 0, endLength: 15)
  move Cap(from: (0, 0), to: (7, -3), scale: 1, angleDeg: 90, mirrorX: true)
  reverse Cap()
export path Cap_turned = from(source: Cap, visible: false)
  export line Hem = segment(start: (0, -20), end: (span, -20))
}
group Sleeves [Ink] {
  instance Left = Sleeve(span: 63, lift: 44)
  instance Right = Sleeve(span: 85, lift: 25)
  move [Right::Cap, Right::Hem](from: (0, 0), to: (120, -10), scale: 1, angleDeg: 0, mirrorX: false)
  const count: number = 3
  const chosen: number = 2
  for i in range(min: 0, max: count, step: 1, showGenerated: true) {
    line Tick = segment(start: (i * 10, -40), end: (i * 10, -35))
  }
  point Pick = offset(from: Tick[chosen].end, dx: 2, dy: 3)
  line Probe = segment(start: (0, -32), end: Pick)
  path Stage = from(source: Left::Cap_turned)
  text Caption = label(text: "SLEEVE", anchor: (3, -10), size: 3)
}
