module Box(Origin: number, Fail: boolean) {
export point Prefix = coordinate(x: Origin, y: 1)
const Side: choice(fail, valid) = if (Fail) { @fail } else { @valid }
const Bad: point = coordinate(x: 1 / 0, y: 5)
const Good0: point = coordinate(x: Origin + 2, y: 5)
const Good1: point = coordinate(x: Origin + 17, y: 13)
const Other: point = coordinate(x: Origin + 40, y: 13)
const Chosen: point[] = match Side { @fail => [Bad,Other] @valid => [Good0,Good1] }
const Ticks: number[] = [1]
for Tick in Ticks carry Carried: point[] = Chosen {
const First: point = Carried[0]
const Second: point = Carried[1]
const Swap: point[] = [Second,First]
next Carried = Swap
}
export line Mark = segment(start: Carried[0], end: Carried[1])
}
instance Dormant(enabled: false) = Box(Origin: 1 / 0, Fail: true)
instance One = Box(Origin: 11, Fail: true)
line UseOne = from(source: One::Mark)
instance Two = Box(Origin: 41, Fail: false)
line UseTwo = from(source: Two::Mark)
point Survivor = coordinate(x: 24, y: -5)

